cases.before_save:
Subject(1,1) = -1.5;
Subject(1,2) = 0;
Subject(1,3) = 2.25;
Subject(2,1) = 3.5;
Subject(2,2) = -4;
Subject(2,3) = 5.75;

cases.setup:
Create Spacecraft Anchor;
Anchor.NAIFId = -101031;
Anchor.NAIFIdReferenceFrame = -910031;
Create Spacecraft Other;
Other.NAIFId = -101032;
Other.NAIFIdReferenceFrame = -910032;
Anchor.DryMass = 833.25;
Other.DryMass = 941.5;
Create Formation Subject;
Subject.Add = {Anchor,Other};

Create Spacecraft Anchor;
Anchor.NAIFId = -101031;
Anchor.NAIFIdReferenceFrame = -910031;
Create EphemerisFile Subject;
Subject.Spacecraft = Anchor;
Subject.Filename = '@FILES@/unused.oem';
Subject.FileFormat = CCSDS-OEM;
Subject.CoordinateSystem = EarthMJ2000Eq;
Subject.StepSize = 60;
Subject.InterpolationOrder = 3;
Subject.WriteEphemeris = false;

Create FileInterface Subject;
Subject.Filename = '@FILES@/input α.sv';
Subject.Format = 'TVHF_ASCII';

Create ThrustSegment Subject;
Subject.ThrustScaleFactor = 1.25;
Subject.MassFlowScaleFactor = 0.8;
Subject.ApplyThrustScaleToMassFlow = true;
Subject.ThrustAngle1 = [1 2];
Subject.ThrustAngle2 = [3 4];

Create ChemicalTank Fuel;
Fuel.FuelMass = 100;
Create ThrustSegment Segment;
Segment.MassSource = {Fuel};
Segment.ThrustScaleFactor = 1.25;
Create ThrustHistoryFile Subject;
Subject.FileName = '@FILES@/history.thf';
Subject.AddThrustSegment = {Segment};

Create Variable Result;
Result = 0;
Create GmatFunction Subject;
Subject.FunctionPath = '@FILES@/Subject.gmf';

fixture_files.Subject.gmf:
function [out] = Subject(input)
Create Variable out;
BeginMissionSequence;
out = 2 * input + 1;
